#include "what_changed/output.hpp"
#include "what_changed/util.hpp"
#include <algorithm>
#include <iterator>
#include <sstream>

namespace wc {
Format parse_format(const std::string&s){if(s=="text")return Format::Text;if(s=="json")return Format::Json;if(s=="markdown"||s=="md")return Format::Markdown;throw std::invalid_argument("unknown format: "+s);}
static Json diff_json(const Diff&d){Json::Array a;a.reserve(d.changes.size());std::transform(d.changes.begin(),d.changes.end(),std::back_inserter(a),[](const Change&c){return Json::Object{{"after",c.after},{"before",c.before},{"category",c.category},{"contextual",c.contextual},{"explanation",c.explanation},{"key",c.key},{"type",c.type}};});Json::Array u;u.reserve(d.unavailable.size());std::transform(d.unavailable.begin(),d.unavailable.end(),std::back_inserter(u),[](const std::string&s){return Json(s);});return Json::Object{{"changes",Json(std::move(a))},{"summary",Json::Object{{"change_count",static_cast<std::int64_t>(d.changes.size())},{"unavailable_count",static_cast<std::int64_t>(d.unavailable.size())}}},{"unavailable",Json(std::move(u))}};}
std::string format_diff(const Diff&d,Format f){if(f==Format::Json)return diff_json(d).dump(true)+"\n";std::ostringstream o;if(f==Format::Markdown)o<<"# what-changed comparison\n\n";if(d.changes.empty())o<<"No semantic changes observed.\n";std::string last;for(const auto&c:d.changes){if(c.category!=last){last=c.category;o<<(f==Format::Markdown?"\n## ":"\n[")<<sanitize_terminal(last)<<(f==Format::Markdown?"\n\n":"]\n");}if(f==Format::Markdown)o<<"- **"<<sanitize_terminal(c.type)<<"** `"<<sanitize_terminal(c.key)<<"`: "<<sanitize_terminal(c.explanation)<<(c.contextual?" _(contextual/transient)_":"")<<"\n";else o<<sanitize_terminal(c.type)<<" "<<sanitize_terminal(c.key)<<": "<<sanitize_terminal(c.explanation)<<(c.contextual?" [contextual/transient]":"")<<"\n  before: "<<sanitize_terminal(c.before.dump())<<"\n  after:  "<<sanitize_terminal(c.after.dump())<<"\n";}if(!d.unavailable.empty()){o<<(f==Format::Markdown?"\n## Unavailable comparisons\n\n":"\n[unavailable]\n");for(const auto&s:d.unavailable)o<<(f==Format::Markdown?"- ":"")<<sanitize_terminal(s)<<"\n";}o<<"\n"<<d.changes.size()<<" observed change(s); "<<d.unavailable.size()<<" unavailable comparison(s). No causal conclusions are made.\n";return o.str();}
std::string format_metadata(const Snapshot&s,Format f){Json::Array cats;cats.reserve(s.categories.size());std::transform(s.categories.begin(),s.categories.end(),std::back_inserter(cats),[](const auto&c){return Json::Object{{"entries",static_cast<std::int64_t>(c.second.entries.size())},{"name",c.first},{"note",c.second.note},{"status",c.second.status}};});Json j=Json::Object{{"application_version",s.application_version},{"captured_at",s.captured_at},{"categories",Json(std::move(cats))},{"schema_version",static_cast<std::int64_t>(s.schema_version)}};if(f==Format::Json)return j.dump(true)+"\n";std::ostringstream o;if(f==Format::Markdown)o<<"# Snapshot metadata\n\n";o<<"Schema version: "<<s.schema_version<<"\nApplication version: "<<sanitize_terminal(s.application_version)<<"\nCaptured at: "<<sanitize_terminal(s.captured_at)<<"\n";for(const auto&c:s.categories)o<<(f==Format::Markdown?"- ":"")<<sanitize_terminal(c.first)<<": "<<c.second.status<<" ("<<c.second.entries.size()<<" entries)"<<(c.second.note.empty()?"":" — "+sanitize_terminal(c.second.note))<<"\n";return o.str();}
}
